#include <cstdio>
#include <cmath>
using namespace juce;
static void check(bool ok,const char*what){if(!ok){fprintf(stderr,"FAIL: %s\n",what);std::abort();}}
static void set(SynthMavenProcessor&p,const String&id,float v){p.parameters.getParameter(id)->setValueNotifyingHost(v);}
static void tick(SynthMavenProcessor&p){AudioBuffer<float>b(2,64);MidiBuffer m;p.processBlock(b,m);}
static void click(Component&c,const String&name){for(int i=0;i<c.getNumChildComponents();i++){auto*child=c.getChildComponent(i);if(auto*b=dynamic_cast<TextButton*>(child))if(b->getButtonText()==name){b->setToggleState(true,dontSendNotification);if(b->onClick)b->onClick();return;}click(*child,name);}}
