 p.storeTuning(0,2);p.resetTuning(0);p.recallTuning(0,2);check(std::abs(p.tuningOffset(0,64)+50)<.001,"five-memory store recall");String edo="19 EDO\n19\n";for(int n=1;n<=19;n++)edo+=String(1200.*n/19,8)+"\n";check(p.loadScala(1,edo,error),"19 EDO import");tick(p);check(std::abs(p.appliedTuningOffset(1,79)+700)<.025,"19 keys span octave");set(p,p.tuningId(1,"bypass"),1);tick(p);check(std::abs(p.appliedTuningOffset(1,79))<.001,"bypass ET");set(p,p.tuningId(1,"bypass"),0);set(p,"masterTuning",1);MemoryBlock saved;p.getStateInformation(saved);SynthMavenProcessor q;q.setStateInformation(saved.getData(),(int)saved.getSize());q.prepareToPlay(48000,64);tick(q);check(q.parameters.getRawParameterValue("masterTuning")->load()>.5,"master toggle persists");set(q,"masterTuning",0);tick(q);check(std::abs(q.appliedTuningOffset(1,79)+700)<.025,"Scala content persists");q.resetTuning(0);q.recallTuning(0,2);check(std::abs(q.tuningOffset(0,64)+50)<.001,"tuning memories persist");check(q.assignMapping(0,23,"masterTuning"),"master toggle MIDI mappable");MidiBuffer midi;AudioBuffer<float>b(2,64);midi.addEvent(MidiMessage::controllerEvent(1,23,127),0);q.processBlock(b,midi);tick(q);check(std::abs(q.appliedTuningOffset(0,62)+50)<.025,"master controlled over MIDI");

 check(MaqamPreset::all().size()==34,"complete canonical reference index");StringArray unique;for(const auto&scale:MaqamPreset::all()){check(!unique.contains(scale.name),"unique maqam name");unique.add(scale.name);auto mapping=MaqamPreset::mapping(scale.ascending);check((mapping.first&1)!=0,"maqam root included");check(juce::countNumberOfBits(mapping.first)==(int)scale.ascending.size(),"every degree has a unique key");for(float cents:mapping.second)check(std::abs(cents)<=200,"keyboard detuning range");}
